// MailboxRelations provides type-safe names for Bun eager-loading.
// Use these instead of string literals in .Relation() calls to get compile-time safety.
//
//	q.Relation(MailboxRelations.Organization)
//	// Bun eager-loads the Organization association via a separate query
var MailboxRelations = struct {
	Organization string
	BusinessUnit string
}{
	Organization: "Organization",
	BusinessUnit: "BusinessUnit",
}

// MailboxScopeTenant restricts a query to a single tenant by adding:
//
//	WHERE imbx.organization_id = ? AND imbx.business_unit_id = ?
//
// Returns the same *bun.SelectQuery so it can be chained fluently:
//
//	inboundmessagecol.MailboxScopeTenant(sq, ti).
//		Where(inboundmessagecol.MailboxColumns.ID.Eq(), id)
func MailboxScopeTenant(q *bun.SelectQuery, ti pagination.TenantInfo) *bun.SelectQuery {
	return buncolgen.ScopeTenant(q, MailboxColumns.OrganizationID, MailboxColumns.BusinessUnitID, ti)
}

// MailboxScopeTenantUpdate restricts an update query to a single tenant.
// Use this inside UpdateQuery.WhereGroup callbacks:
//
//	WhereGroup(" AND ", func(uq *bun.UpdateQuery) *bun.UpdateQuery {
//		return inboundmessagecol.MailboxScopeTenantUpdate(uq, req.TenantInfo).
//			Where(inboundmessagecol.MailboxColumns.ID.In(), bun.List(ids))
//	})
func MailboxScopeTenantUpdate(q *bun.UpdateQuery, ti pagination.TenantInfo) *bun.UpdateQuery {
	return buncolgen.ScopeTenantUpdate(q, MailboxColumns.OrganizationID, MailboxColumns.BusinessUnitID, ti)
}

// MailboxScopeTenantDelete restricts a delete query to a single tenant.
// Use this inside DeleteQuery.WhereGroup callbacks:
//
//	WhereGroup(" AND ", func(dq *bun.DeleteQuery) *bun.DeleteQuery {
//		return inboundmessagecol.MailboxScopeTenantDelete(dq, req.TenantInfo).
//			Where(inboundmessagecol.MailboxColumns.ID.Eq(), id)
//	})
func MailboxScopeTenantDelete(q *bun.DeleteQuery, ti pagination.TenantInfo) *bun.DeleteQuery {
	return buncolgen.ScopeTenantDelete(q, MailboxColumns.OrganizationID, MailboxColumns.BusinessUnitID, ti)
}

// MailboxApplyTenant returns a closure for SelectQuery.Apply() that scopes to a single tenant.
// Use this instead of wrapping ScopeTenant in an anonymous function:
//
//	q.Apply(inboundmessagecol.MailboxApplyTenant(tenantInfo))
func MailboxApplyTenant(ti pagination.TenantInfo) func(*bun.SelectQuery) *bun.SelectQuery {
	return buncolgen.ApplyTenant(MailboxColumns.OrganizationID, MailboxColumns.BusinessUnitID, ti)
}

